import PasswordInputSchema from '@melt-js/comps-vue3/src/components/PasswordInput.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const PasswordInput = remoteComponent('PasswordInput')

const pwd = ref('')
const pwd2 = ref('')
const pwd3 = ref('')
const lastAction = ref('还没按回车')

const stageStyle = {
