  gap: '22px',
  alignItems: 'center',
  justifyContent: 'center',
  height: '420px',
  padding: '48px 24px',
  background: '#f8fafc',
}

function onEnter() {
  lastAction.value = `在「登录密码」里按了回车，当前 ${pwd.value.length} 位`
}
</script>

